param([string]$ArchivistRoot="D:\Archivist")
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$Side=Join-Path $ArchivistRoot 'sidecars\auto_edit';$Ptr=Join-Path $Side 'current.txt';if(!(Test-Path $Ptr)){throw 'V48 sidecar not activated'};$Slot=(Get-Content $Ptr -Raw).Trim();$Rel=Join-Path (Join-Path $Side 'releases') $Slot
$Desktop=[Environment]::GetFolderPath('Desktop');$W=New-Object -ComObject WScript.Shell
$items=@(@('MediaEngine - Open Auto Edit Inbox','Open_Auto_Edit_Inbox_V37.vbs'),@('MediaEngine - Start Auto Edit','Start_Auto_Edit_Inbox_V37.vbs'),@('MediaEngine - Auto Edit Status','Open_Auto_Edit_Status_V37.vbs'),@('MediaEngine - Open Auto Edit Output','Open_Auto_Edit_Output_V37.vbs'),@('MediaEngine - Open Latest Auto Edit Result','Open_Latest_Auto_Edit_Result_V37.vbs'),@('MediaEngine - Open Latest Auto Alternatives','Open_Latest_Auto_Alternatives_V37.vbs'),@('MediaEngine - Compare Auto Alternatives','Open_Latest_Variant_Comparison_V37.vbs'),@('MediaEngine - Approve Latest Alternative A','Approve_Latest_Alternative_A_V37.vbs'),@('MediaEngine - Approve Latest Alternative B','Approve_Latest_Alternative_B_V37.vbs'),@('MediaEngine - Edit Latest Auto Edit Selection','Edit_Latest_Auto_Edit_Selection_V37.vbs'),@('MediaEngine - Apply Latest Auto Edit Override','Apply_Latest_Auto_Edit_Override_V37.vbs'),@('MediaEngine - Approve Latest Automatic Cut','Approve_Latest_Automatic_Cut_V37.vbs'),@('MediaEngine - Approve Latest Override','Approve_Latest_Override_V37.vbs'),@('MediaEngine - Open Latest Approved Auto Edit','Open_Latest_Approved_Auto_Edit_V37.vbs'),@('MediaEngine - Edit Review Choice','Edit_Latest_Review_Choice_V38.vbs'),@('MediaEngine - Apply Review Choice','Apply_Latest_Review_Choice_V38.vbs'))
foreach($x in $items){$script=Join-Path $Rel $x[1];if(!(Test-Path $script)){throw "missing script: $script"};$lnk=$W.CreateShortcut((Join-Path $Desktop ($x[0]+'.lnk')));$lnk.TargetPath=(Join-Path $env:WINDIR 'System32\wscript.exe');$lnk.Arguments='"'+$script+'"';$lnk.WorkingDirectory=$Rel;$lnk.Save()}
Write-Output 'V48_DESKTOP_SHORTCUTS_CREATED'
